<section class="form-panel"><p class="eyebrow">ZIP</p><h2>Importar archivo ZIP</h2><p class="muted">Preserva carpetas, subcarpetas y omite archivos temporales o duplicados.</p><form method="post" enctype="multipart/form-data" class="form-grid"><?=csrf_field()?><input type="hidden" name="accion" value="subir_zip"><input type="hidden" name="sector_id" value="<?=$sid?>"><label>Carpeta base<select name="carpeta_id"><option value="">Raíz del sector</option><?php foreach($folders as $f):?><option value="<?=$f['id']?>"><?=h($f['label'])?></option><?php endforeach;?></select></label><label>Archivo ZIP<input type="file" name="zip" accept=".zip,application/zip" required></label><?=documentMetaFields()?><button class="btn primary">Importar ZIP</button></form></section></div>
